typedef unsigned int size_t;

void *operator new(size_t, unsigned int, const char *, int);
extern void arch_free(void *);

class ref
{
protected:
  unsigned count;

public:
  ref() : count(0) {}
  unsigned refs() const { return count; }
  void addref() { ++count; }
  bool subref() { return --count != 0; }
};

template<class T>
class vector
{
  T *first;
  T *last;
  T *limit;

public:
  vector() : first(0), last(0), limit(0) {}
  ~vector()
  {
    for (T *p = first; p < last; ++p)
      p->~T();
    if (last - first)
      arch_free(first);
  }
};

class color
{
public:
  float r, g, b, a;
  color(float R, float G, float B, float A) : r(R), g(G), b(B), a(A) {}
};

class sphere
{
  float data[4];
};

class light_manager : public ref
{
public:
  class light_rec
  {
    char data[76];
  public:
    ~light_rec() {}
  };

  vector<light_rec> lights;
  color last_ambient;
  color goal_ambient;
  color my_ambient;
  unsigned max_lights;
  unsigned cur_max_lights;
  sphere bound;
  bool allow_omni;
  bool dynamic_only;

  explicit light_manager(bool is_terrain=false)
    : last_ambient(1.0f,1.0f,1.0f,1.0f)
    , goal_ambient(1.0f,1.0f,1.0f,1.0f)
    , my_ambient(1.0f,1.0f,1.0f,1.0f)
    , max_lights(1)
    , allow_omni(is_terrain)
    , dynamic_only(is_terrain)
  {}
};

template<class T>
class refptr
{
  T *p;

  void subref()
  {
    if (p)
      if (!p->subref())
        delete p;
  }

  void addref()
  {
    if (p)
      p->addref();
  }

public:
  refptr(T *a=0) : p(a) { addref(); }

  refptr<T>& operator=(T *a)
  {
    if (p != a)
    {
      subref();
      p = a;
      addref();
    }
    return *this;
  }
};

static refptr<light_manager> static_light_set=0;

#define NEW new(0,__FILE__,__LINE__)

void LIGHTMGR_StaticInitLightSet( void )
{
	static_light_set=NEW light_manager(true);
}
